css:
.absolute {
  position: absolute
}

.relative {
  position: relative
}

.left-\[3\%\] {
  left: 3%
}

.top-1\/2 {
  top: 50%
}

.block {
  display: block
}

.hidden {
  display: none
}

.aspect-\[2\/0\.75\] {
  aspect-ratio: 2/0.75
}

.aspect-square {
  aspect-ratio: 1 / 1
}

.h-\[90\%\] {
  height: 90%
}

.w-20 {
  width: 5rem
}

.-translate-y-1\/2 {
  --tw-translate-y: -50%;
  transform: translate(var(--tw-translate-x), var(--tw-translate-y)) rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y)) scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y))
}

.rotate-180 {
  --tw-rotate: 180deg;
  transform: translate(var(--tw-translate-x), var(--tw-translate-y)) rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y)) scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y))
}

.cursor-pointer {
  cursor: pointer
}

.rounded-full {
  border-radius: 9999px
}

.bg-white {
  --tw-bg-opacity: 1;
  background-color: rgb(255 255 255 / var(--tw-bg-opacity))
}

.bg-gradient-to-r {
  background-image: linear-gradient(to right, var(--tw-gradient-stops))
}

.from-red-600 {
  --tw-gradient-from: #dc2626 var(--tw-gradient-from-position);
  --tw-gradient-to: rgb(220 38 38 / 0) var(--tw-gradient-to-position);
  --tw-gradient-stops: var(--tw-gradient-from), var(--tw-gradient-to)
}

.to-green-600 {
  --tw-gradient-to: #16a34a var(--tw-gradient-to-position)
}

.bg-\[length\:100\%_100\%\] {
  background-size: 100% 100%
}

.shadow-2xl {
  --tw-shadow: 0 25px 50px -12px rgb(0 0 0 / 0.25);
  --tw-shadow-colored: 0 25px 50px -12px var(--tw-shadow-color);
  box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow)
}

.shadow-purple-300 {
  --tw-shadow-color: #d8b4fe;
  --tw-shadow: var(--tw-shadow-colored)
}

.transition-all {
  transition-property: all;
  transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
  transition-duration: 150ms
}

.duration-500 {
  transition-duration: 500ms
}

.hover\:bg-\[length\:100\%_500\%\]:hover {
  background-size: 100% 500%
}

.focus\:bg-\[length\:100\%_500\%\]:focus {
  background-size: 100% 500%
}

.peer\/input:checked ~ .peer-checked\/input\:left-\[63\%\] {
  left: 63%
}

.peer\/input:checked ~ .peer-checked\/input\:-rotate-6 {
  --tw-rotate: -6deg;
  transform: translate(var(--tw-translate-x), var(--tw-translate-y)) rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y)) scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y))
}

.\[\&\:has\(input\:checked\)\]\:rotate-180:has(input:checked) {
  --tw-rotate: 180deg;
  transform: translate(var(--tw-translate-x), var(--tw-translate-y)) rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y)) scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y))
}
